def normalize(path):
    if not path:
        return '.'

    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '.':
            continue
        elif part == '..':
            if stack and stack[-1] != '':
                stack.pop()
        else:
            stack.append(part)

    normalized_path = '/'.join(stack)

    if normalized_path.startswith('//'):
        normalized_path = '/' + normalized_path[1:]

    return normalized_path or '/'
```

