class EventBus:
    def __init__(self):
        self.events = {}

    def on(self, event, fn):
        if event not in self.events:
            self.events[event] = []
        self.events[event].append(fn)

    def off(self, event, fn):
        if event in self.events:
            self.events[event].remove(fn)
            if not self.events[event]:
                del self.events[event]

